 static String tr(Context c,String j,String e,String z){return PanelUi.tr(c,j,e,z);}
 static LocalPlaylistData read(Context c){try{return new LocalPlaylistData(PreferenceManager.getDefaultSharedPreferences(c).getString(KEY,"{}"));}catch(JSONException e){throw new IllegalStateException("Invalid local playlist store",e);}}
 static boolean save(Context c,LocalPlaylistData d){boolean ok=PreferenceManager.getDefaultSharedPreferences(c).edit().putString(KEY,d.toString()).commit();if(!ok)Toast.makeText(c,tr(c,"保存に失敗しました","Unable to save","儲存失敗"),1).show();return ok;}
 static void choose(Context host,String current,java.util.function.Consumer<String> chosen){Context c=PlaybackSession.dialogContext(host);LocalPlaylistData d=read(host);ArrayList<String> ids=new ArrayList<>(),names=new ArrayList<>();if(!"".equals(current)){ids.add("");names.add(tr(c,"プレイリスト","Playlists","播放清單"));}for(int n=0;n<d.folders.length();n++){JSONObject f=d.folders.optJSONObject(n);if(!f.optString("id").equals(current)){ids.add(f.optString("id"));names.add(f.optString("name"));}}names.add(tr(c,"フォルダーを作成","Create folder","建立資料夾"));UiDialogs.show(new AlertDialog.Builder(c).setTitle(tr(c,"フォルダーを選択","Select folder","選擇資料夾")).setItems(names.toArray(new String[0]),(x,w)->{if(w<ids.size())chosen.accept(ids.get(w));else create(host,chosen);}).setNegativeButton(tr(c,"キャンセル","Cancel","取消"),null).create());}
 static void confirmFolderDelete(Activity host,String id,String name,Runnable done){if(id==null||id.isEmpty())return;Context c=PlaybackSession.dialogContext(host);UiDialogs.show(new AlertDialog.Builder(c).setTitle(tr(c,"フォルダーを削除しますか？","Delete folder?","刪除資料夾？")).setMessage(name+"\n"+tr(c,"フォルダー内の動画は未分類に移動します。","Videos in this folder will move to Unfiled.","資料夾中的影片會移至未分類。" )).setPositiveButton(tr(c,"削除","Delete","刪除"),(d,w)->{try{LocalPlaylistData data=read(host);data.removeFolder(id);if(save(host,data))done.run();}catch(Exception e){Toast.makeText(host,tr(host,"削除に失敗しました","Unable to delete folder","刪除失敗"),1).show();}}).setNegativeButton(tr(c,"キャンセル","Cancel","取消"),null).create());}
