 private static void add(Context host,String url,String title,String owner,String image,Object row){choose(host,null,folder->{try{LocalPlaylistData d=read(host);d.add(folder,url,title,owner,image);String videoId=HistoryRules.id(url);if(row!=null)for(int n=0;n<d.videos.length();n++){JSONObject v=d.videos.getJSONObject(n);if(folder.equals(v.optString("folder"))&&videoId.equals(v.optString("videoId")))for(String key:new String[]{"length","videoinfo","posttime"})v.put(key,ListActions.value(row,key));}if(save(host,d))Toast.makeText(host,tr(host,"プレイリストに追加しました","Added to playlist","已加入播放清單"),0).show();}catch(Exception e){Toast.makeText(host,tr(host,"追加に失敗しました","Unable to add video","新增失敗"),1).show();}});}
