 static boolean superLong(Object adapter,Object row){Page page=ADAPTER_PAGES.get(adapter);if(page==null||page.selecting)return page!=null;String url=ListActions.value(row,"videourl");for(JSONObject video:page.visible)if(url.equals(video.optString("url"))){page.selecting=true;page.toggle(video.optString("id"));return true;}return false;}
 static void withAdapterMode(Activity host,Object adapter,Runnable action){Page page=ADAPTER_PAGES.get(adapter);if(page==null||(!page.continuous&&!page.shuffle)){action.run();return;}Class<?> list;java.lang.reflect.Field enabled,mode;boolean oldEnabled;int oldMode;try{list=Class.forName("com.sauzask.nicoid.NicoidVideoListActivity");enabled=list.getField("I");mode=list.getField("J");oldEnabled=enabled.getBoolean(null);oldMode=mode.getInt(null);enabled.setBoolean(null,true);}catch(Exception e){android.util.Log.w("nicoid-playlist","Unable to apply folder playback mode",e);action.run();return;}try{PlaylistPlayback.withMode(page.shuffle,action);}finally{try{enabled.setBoolean(null,oldEnabled);mode.setInt(null,oldMode);}catch(Exception e){android.util.Log.w("nicoid-playlist","Unable to restore folder playback mode",e);}}}
 public static boolean home(Activity a,MenuItem item){return item.getItemId()==android.R.id.home&&back(a);}
 public static boolean back(Activity a){Page p=PAGES.get(a);if(p==null)return false;if(p.selecting){p.selecting=false;p.selected.clear();p.render();return true;}if(p.folder!=null){p.folder=null;p.render();return true;}return false;}
