 public static boolean menuOrFeed(Activity a,Menu menu){if(options(a,menu))return true;try{return (Boolean)Class.forName("e.e.a.FollowFeed").getMethod("menu",Activity.class,Menu.class).invoke(null,a,menu);}catch(Exception e){return false;}}
