 @SuppressWarnings({"rawtypes","unchecked"})public static void menu(Context c,ArrayList rows){for(int n=0;n<rows.size();n++){Object row=rows.get(n);if(!(row instanceof Map))continue;Object intent=((Map)row).get("intent");if(intent instanceof Intent){String target=((Intent)intent).getComponent()==null?"":((Intent)intent).getComponent().getClassName();if(target.endsWith("NicoidVideoListActivity")&&((Intent)intent).getIntExtra("type",-1)==8){Map entry=new HashMap();entry.put("title",tr(c,"プレイリスト","Playlists","播放清單"));entry.put("subtitle",tr(c,"本体に保存した動画のリスト","Video lists saved on this device","儲存在此裝置的影片清單"));entry.put("islabel",false);entry.put("type",0);entry.put("intent",new Intent().setClassName(c,"com.sauzask.nicoid.NicoidNicorepoActivity").putExtra("nicoid_local_playlists",true));rows.add(n+1,entry);return;}}}}
